"use client";
import {useEffect,useState} from "react";
import {BadgeEuro,FileText,Landmark,TriangleAlert} from "lucide-react";
import PageTitle from "@/composants/ui/PageTitle";
import Section from "@/composants/ui/Section";
import serviceFinance from "@/services/ServiceFinance";
import serviceSignalement from "@/services/ServiceSignalement";
export default function Page(){const [data,setData]=useState({invoices:[],payouts:[]});const[reports,setReports]=useState([]);useEffect(()=>{serviceFinance.getAll().then(setData);serviceSignalement.getAll().then(x=>{const rows=Array.isArray(x)?x:(x?.data||[]);setReports(rows.filter(r=>r.type==="probleme_paiement"));});},[]);const due=data.invoices.filter(i=>i.status!=="payee").reduce((s,i)=>s+i.amount,0);const payout=data.payouts.filter(i=>i.status!=="paye").reduce((s,i)=>s+i.amount,0);const cards=[[FileText,"Factures à suivre",data.invoices.filter(i=>i.status!=="payee").length],[BadgeEuro,"Montant commerçants",`${due.toFixed(2)} €`],[Landmark,"À verser aux relais",`${payout.toFixed(2)} €`],[TriangleAlert,"Litiges paiement",reports.length]];return <div className="space-y-8"><PageTitle title="Gestion financière" description="Suivez les factures commerçants, les rémunérations relais et les litiges de paiement."/><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([I,l,v])=><div key={l} className="rf-panel p-5"><I size={20} className="text-blue-700"/><p className="mt-4 text-2xl font-black text-slate-950">{v}</p><p className="mt-1 text-sm text-slate-600">{l}</p></div>)}</div><Section title="Règles financières"><div className="grid gap-4 md:grid-cols-2"><div className="rounded-2xl bg-slate-50 p-5"><p className="text-sm text-slate-600">Abonnement commerçant</p><p className="mt-2 text-2xl font-black">19,90 € / mois</p></div><div className="rounded-2xl bg-slate-50 p-5"><p className="text-sm text-slate-600">Rémunération point relais</p><p className="mt-2 text-2xl font-black">1,50 € / colis retiré</p></div></div></Section></div>}
